package dev.twob2tkit.runtime.engine;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class LocalFarmMeleePolicyTest {
 boolean ok(String server,boolean scoped,boolean survival,double hp,boolean grounded,boolean flying,boolean manual,boolean screen,boolean fire,boolean pose,boolean target){return LocalFarmMeleePolicy.allowed(server,scoped,survival,hp,20,grounded,flying,manual,screen,true,fire,pose,target);}
 @Test void onlyUnnamedLivingCapturedPiglinsAreTargets(){assertTrue(LocalFarmMeleePolicy.capturedTarget("minecraft:zombified_piglin",true,true,false));assertFalse(LocalFarmMeleePolicy.capturedTarget("minecraft:player",true,true,false));assertFalse(LocalFarmMeleePolicy.capturedTarget("minecraft:zombified_piglin",true,false,false));assertFalse(LocalFarmMeleePolicy.capturedTarget("minecraft:zombified_piglin",true,true,true));}
 @Test void safeHalfSlabPoseRejectsTheOldHighStep(){assertTrue(LocalFarmMeleePolicy.playerAtStation(.5,240.5,.5));assertFalse(LocalFarmMeleePolicy.playerAtStation(.5,241,.5));assertFalse(LocalFarmMeleePolicy.targetAtStation(.5,241,.5));}
 @Test void sideFootRayCanClearThinSupportWithoutPassingThroughIt(){var pane=new net.minecraft.world.phys.AABB(.4375,243,.4375,.5625,244,.5625);var eye=new net.minecraft.world.phys.Vec3(.5,242.12,.5);var centre=new net.minecraft.world.phys.Vec3(.5,244.01,.5);var edge=new net.minecraft.world.phys.Vec3(.73,244.01,.5);assertTrue(pane.clip(eye,centre).isPresent());assertTrue(pane.clip(eye,edge).isEmpty());assertTrue(eye.distanceTo(edge)<2.9);}
 @Test void oneSourceWaitsForBothWallTimeTicksAndFullCharge(){assertFalse(LocalFarmMeleePolicy.attackDue(1499,100,0,0,1));assertFalse(LocalFarmMeleePolicy.attackDue(1500,29,0,0,1));assertFalse(LocalFarmMeleePolicy.attackDue(1500,30,0,0,.9f));assertTrue(LocalFarmMeleePolicy.attackDue(1500,30,0,0,1));}
 @Test void physicalQuarterBlockStandShiftStaysInsideItsOriginalSupport(){assertTrue(LocalFarmMeleePolicy.targetAtStation(.25,244.0625,.75));assertTrue(LocalFarmMeleePolicy.targetAtStation(.5,244,.5));assertFalse(LocalFarmMeleePolicy.targetAtStation(.9,244,.5));assertFalse(LocalFarmMeleePolicy.targetAtStation(.5,246,.5));assertFalse(LocalFarmMeleePolicy.targetAtStation(Double.NaN,244,.5));}
 @Test void manualMeteorRefusalRequiresANewRequest(){assertFalse(LocalFarmMeleePolicy.offerAllowed("old","old"));assertTrue(LocalFarmMeleePolicy.offerAllowed("new","old"));assertFalse(LocalFarmMeleePolicy.offerAllowed("", "old"));}
 @Test void onlyHealthyGroundedScopedLocalTrialMayBorrowTarget(){assertTrue(ok("127.0.0.1:25579",true,true,20,true,false,false,false,false,true,true));}
 @Test void remoteAndWrongLocalServersNeverActivate(){for(String s:new String[]{"simpcraft.com","localhost:25579","127.0.0.1:25565",""})assertFalse(ok(s,true,true,20,true,false,false,false,false,true,true));}
 @Test void expiredForeignAndCreativeSessionsRefuse(){assertFalse(ok("127.0.0.1:25579",false,true,20,true,false,false,false,false,true,true));assertFalse(ok("127.0.0.1:25579",true,false,20,true,false,false,false,false,true,true));}
 @Test void healthManualAndInterfacesWin(){assertFalse(ok("127.0.0.1:25579",true,true,18,true,false,false,false,false,true,true));assertFalse(ok("127.0.0.1:25579",true,true,Double.NaN,true,false,false,false,false,true,true));assertFalse(ok("127.0.0.1:25579",true,true,20,true,false,true,false,false,true,true));assertFalse(ok("127.0.0.1:25579",true,true,20,true,false,false,true,false,true,true));}
 @Test void airFlightAndMovedPoseCannotKeepSweeping(){assertFalse(ok("127.0.0.1:25579",true,true,20,false,false,false,false,false,true,true));assertFalse(ok("127.0.0.1:25579",true,true,20,true,true,false,false,false,true,true));assertFalse(ok("127.0.0.1:25579",true,true,20,true,false,false,false,false,false,true));}
 @Test void fireAspectOrMissingTargetRefuses(){assertFalse(ok("127.0.0.1:25579",true,true,20,true,false,false,false,true,true,true));assertFalse(ok("127.0.0.1:25579",true,true,20,true,false,false,false,false,true,false));}
}
